class Solution:
    def maximumBeauty(self, flowers: List[int]) -> int:
        n = len(flowers)
        pre = [0] * (n + 1)
        for i, x in enumerate(flowers):
            pre[i + 1] = pre[i] + max(0, x)
        ans = float('-inf')
        for l in range(n):
            for r in range(l + 1, n):
                if flowers[l] == flowers[r]:
                    ans = max(ans, 2 * flowers[l] + pre[r] - pre[l + 1])
        return ans

