class Solution:
    def maximumBeauty(self, flowers: List[int]) -> int:
        best = {}
        pos_pref = 0
        ans = float('-inf')
        for x in flowers:
            if x in best:
                ans = max(ans, 2 * x + pos_pref - best[x])
            else:
                best[x] = pos_pref + max(0, x)
            if x > 0:
                pos_pref += x
        return ans

