class Solution {
public:
    int maximumBeauty(vector<int>& flowers) {
        unordered_map<int, long long> best;
        long long posPref = 0, ans = LLONG_MIN;
        for (int x : flowers) {
            auto it = best.find(x);
            if (it != best.end())
                ans = max(ans, 2LL * x + posPref - it->second);
            else
                best[x] = posPref + max(0, x);
            if (x > 0) posPref += x;
        }
        return (int)ans;
    }
};

