class Solution {
    public int maximumBeauty(int[] flowers) {
        Map<Integer, Long> best = new HashMap<>();
        long posPref = 0, ans = Long.MIN_VALUE;
        for (int x : flowers) {
            Long stored = best.get(x);
            if (stored != null)
                ans = Math.max(ans, 2L * x + posPref - stored);
            else
                best.put(x, posPref + Math.max(0, x));
            if (x > 0) posPref += x;
        }
        return (int) ans;
    }
}

